1. SELECT at.voltage_class, COUNT(*) AS asset_count FROM asset_types at JOIN assets a ON at.asset_type_id = a.asset_type_id GROUP BY at.voltage_class ORDER BY at.voltage_class;
2. SELECT at.voltage_class, COUNT(a.asset_id) AS number_of_assets FROM assets a JOIN asset_types at ON a.asset_type_id = at.asset_type_id GROUP BY at.voltage_class ORDER BY at.voltage_class DESC;
3. SELECT at.voltage_class, COUNT(*) AS total_assets FROM asset_types at INNER JOIN assets a USING(asset_type_id) GROUP BY at.voltage_class ORDER BY at.voltage_class ASC;
